import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.em2JOrjF.js";const d=JSON.parse('{"title":"Logging time","description":"","frontmatter":{},"headers":[],"relativePath":"guide/logging-time.md","filePath":"guide/logging-time.md"}'),i={name:"guide/logging-time.md"};function n(s,e,l,h,u,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="logging-time" tabindex="-1">Logging time <a class="header-anchor" href="#logging-time" aria-label="Permalink to &quot;Logging time&quot;">​</a></h1><p>The simplest thing VERA does is record your hours. Tell them what you worked on and they handle the rest.</p><hr><h2 id="what-to-say" tabindex="-1">What to say <a class="header-anchor" href="#what-to-say" aria-label="Permalink to &quot;What to say&quot;">​</a></h2><p>VERA needs two things: a project and a duration. Everything else is optional.</p><blockquote><p>&quot;Log 4 hours on Nike campaign, design&quot;</p></blockquote><blockquote><p>&quot;3.5h on Adidas, video editing&quot;</p></blockquote><blockquote><p>&quot;Can you add 2 hours to the internal training project&quot;</p></blockquote><p>If you have a single work plan (envelope) on a project, VERA uses it automatically — you don&#39;t need to say what type of work it is. If you&#39;re doing multiple types of work on the same project, they&#39;ll ask which one applies.</p><h3 id="specifying-a-date" tabindex="-1">Specifying a date <a class="header-anchor" href="#specifying-a-date" aria-label="Permalink to &quot;Specifying a date&quot;">​</a></h3><p>Entries default to today. For past dates:</p><blockquote><p>&quot;Log 3 hours on Nike for yesterday, design work&quot;</p></blockquote><blockquote><p>&quot;Add 4h to Adidas for last Monday, development&quot;</p></blockquote><blockquote><p>&quot;3h on the BA project, 15th March, research&quot;</p></blockquote><hr><h2 id="checking-your-hours" tabindex="-1">Checking your hours <a class="header-anchor" href="#checking-your-hours" aria-label="Permalink to &quot;Checking your hours&quot;">​</a></h2><blockquote><p>&quot;How many hours have I logged this week?&quot;</p></blockquote><blockquote><p>&quot;Show me my time entries for this week&quot;</p></blockquote><blockquote><p>&quot;What did I log last week?&quot;</p></blockquote><p>VERA returns a breakdown by project and task.</p><hr><h2 id="fixing-a-mistake" tabindex="-1">Fixing a mistake <a class="header-anchor" href="#fixing-a-mistake" aria-label="Permalink to &quot;Fixing a mistake&quot;">​</a></h2><p>If you logged the wrong number of hours or the wrong project, ask VERA to correct it:</p><blockquote><p>&quot;Actually that last entry should be 3.5 hours, not 4&quot;</p></blockquote><blockquote><p>&quot;Can you change my Nike entry from yesterday to video editing instead of design?&quot;</p></blockquote><p>VERA will confirm what they&#39;re changing before making the edit.</p><p>To remove an entry entirely:</p><blockquote><p>&quot;Delete my Nike entry from yesterday&quot;</p></blockquote><hr><h2 id="logging-for-someone-else" tabindex="-1">Logging for someone else <a class="header-anchor" href="#logging-for-someone-else" aria-label="Permalink to &quot;Logging for someone else&quot;">​</a></h2><p>Managers and owners can log time on behalf of a team member:</p><blockquote><p>&quot;Log 6 hours for Sarah on the Adidas project, development&quot;</p></blockquote><p>This is typically used for sick days or leave — see <a href="./time-off.html">Time off</a> for how that works.</p><hr><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>What if I&#39;m not sure which project to log to?</strong> Say the project name as you know it — VERA will find the closest match. If there&#39;s ambiguity they&#39;ll ask you to confirm.</p><p><strong>What&#39;s a &quot;task&quot;?</strong> Tasks are categories of work: Design, Development, Strategy, Admin, and so on. Your team may have a specific set enabled for each project. If you have one type of work planned on a project, VERA applies it automatically. If there are multiple, they&#39;ll ask. To see which tasks are available: &quot;What tasks are on the Nike project?&quot;</p><p><strong>Can I log time in a public channel?</strong> Yes. VERA responds wherever they&#39;ve been added. Your entries are recorded the same way regardless of where you send the message.</p><p><strong>What if I forget to log for a few days?</strong> Just log them when you remember, specifying the date. VERA doesn&#39;t impose time limits on past entries.</p>',39)])])}const g=o(i,[["render",n]]);export{d as __pageData,g as default};
